import React, { useState, useEffect } from 'react';
import './App.css';
import Login from './pages/Login';
import Dashboard from './pages/Dashboard';
import Header from './components/Header';
import Sidebar from './components/Sidebar';
import Analytics from './pages/Analytics';
import Reports from './pages/Reports';
import CustomerInvoice from './pages/CustomerInvoice';
import Settings from './pages/Settings';

function App() {
  const [token, setToken] = useState(null);
  const [currentPage, setCurrentPage] = useState('dashboard');
  const [stats, setStats] = useState({ total: 0, anomalies: 0, normal: 0 });
  const [notifications, setNotifications] = useState([]);

  useEffect(() => {
    const savedToken = localStorage.getItem('token');
    if (savedToken) {
      setToken(savedToken);
    }
  }, []);

  useEffect(() => {
    if (token) {
      localStorage.setItem('token', token);
    } else {
      localStorage.removeItem('token');
    }
  }, [token]);

  const addNotification = (message, type = 'info') => {
    const notification = {
      id: Date.now(),
      message,
      type,
      timestamp: new Date().toISOString()
    };
    setNotifications(prev => [notification, ...prev.slice(0, 9)]); // Keep last 10
  };

  const handleLogout = () => {
    setToken(null);
    setCurrentPage('dashboard');
    setStats({ total: 0, anomalies: 0, normal: 0 });
    setNotifications([]);
  };

  if (!token) {
    return <Login setToken={setToken} />;
  }

  const renderCurrentPage = () => {
    switch(currentPage) {
      case 'dashboard':
        return <Dashboard token={token} setToken={setToken} setStats={setStats} addNotification={addNotification} />;
      case 'analytics':
        return <Analytics token={token} />;
      case 'reports':
        return <Reports token={token} setStats={setStats} />;
      case 'customers':
        return <CustomerInvoice token={token} />;
      case 'settings':
        return <Settings token={token} />;
      default:
        return <Dashboard token={token} setToken={setToken} setStats={setStats} addNotification={addNotification} />;
    }
  };

  return (
    <div className="app">
      <Sidebar currentPage={currentPage} setCurrentPage={setCurrentPage} onLogout={handleLogout} />
      <div className="main-content">
        <Header currentPage={currentPage} stats={stats} setCurrentPage={setCurrentPage} />
        {renderCurrentPage()}
      </div>
    </div>
  );
}

export default App;
